import React, { useEffect, useState } from 'react';

const Chart = ({ symbol = 'BTCUSD', timeframe = '1H', patterns = [] }) => {
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState(null);

  // Simple fallback chart component
  const FallbackChart = () => {
    return (
      <div className="w-full h-full bg-gray-900 rounded-lg border border-gray-700 flex flex-col">
        <div className="p-4 border-b border-gray-700">
          <div className="flex items-center justify-between">
            <div>
              <h3 className="text-white font-semibold">{symbol}</h3>
              <p className="text-gray-400 text-sm">{timeframe} • Fallback Chart</p>
            </div>
            <div className="text-right">
              <div className="text-green-400 font-mono text-lg">$42,350.00</div>
              <div className="text-green-400 text-sm">+2.5% (+$1,050.00)</div>
            </div>
          </div>
        </div>
        
        <div className="flex-1 p-4 relative">
          {/* Simple price chart simulation */}
          <svg className="w-full h-full" viewBox="0 0 800 400">
            <defs>
              <linearGradient id="priceGradient" x1="0%" y1="0%" x2="0%" y2="100%">
                <stop offset="0%" stopColor="#10b981" stopOpacity="0.3"/>
                <stop offset="100%" stopColor="#10b981" stopOpacity="0"/>
              </linearGradient>
            </defs>
            
            {/* Grid lines */}
            {[...Array(8)].map((_, i) => (
              <line 
                key={`h-${i}`}
                x1="0" 
                y1={i * 50} 
                x2="800" 
                y2={i * 50} 
                stroke="#374151" 
                strokeWidth="1"
                opacity="0.3"
              />
            ))}
            {[...Array(16)].map((_, i) => (
              <line 
                key={`v-${i}`}
                x1={i * 50} 
                y1="0" 
                x2={i * 50} 
                y2="400" 
                stroke="#374151" 
                strokeWidth="1"
                opacity="0.3"
              />
            ))}
            
            {/* Sample price line */}
            <path
              d="M 0,300 Q 100,250 200,200 T 400,150 T 600,100 T 800,120"
              fill="none"
              stroke="#10b981"
              strokeWidth="2"
            />
            
            {/* Area under curve */}
            <path
              d="M 0,300 Q 100,250 200,200 T 400,150 T 600,100 T 800,120 L 800,400 L 0,400 Z"
              fill="url(#priceGradient)"
            />
            
            {/* Sample pattern overlay */}
            {patterns.length > 0 && (
              <g>
                <circle cx="200" cy="200" r="4" fill="#f59e0b" />
                <circle cx="400" cy="150" r="4" fill="#f59e0b" />
                <circle cx="600" cy="100" r="4" fill="#f59e0b" />
                <circle cx="700" cy="120" r="4" fill="#f59e0b" />
                <path
                  d="M 200,200 L 400,150 L 600,100 L 700,120"
                  fill="none"
                  stroke="#f59e0b"
                  strokeWidth="2"
                  strokeDasharray="5,5"
                />
                <text x="450" y="140" fill="#f59e0b" fontSize="12" textAnchor="middle">
                  Gartley Pattern
                </text>
              </g>
            )}
          </svg>
          
          <div className="absolute top-4 left-4 bg-gray-800 rounded p-2">
            <div className="text-white text-xs space-y-1">
              <div>O: $42,100.00</div>
              <div>H: $42,450.00</div>
              <div>L: $41,800.00</div>
              <div>C: $42,350.00</div>
            </div>
          </div>
        </div>
      </div>
    );
  };

  useEffect(() => {
    setIsLoading(false);
    setError(null);
    
    // Generate sample price data
    const sampleData = Array.from({ length: 100 }, (_, i) => ({
      time: Date.now() - (100 - i) * 60000,
      open: 42000 + Math.random() * 1000,
      high: 42000 + Math.random() * 1200,
      low: 41800 + Math.random() * 800,
      close: 42000 + Math.random() * 1000,
      volume: Math.random() * 1000000
    }));
    
    setPriceData(sampleData);
  }, [symbol, timeframe]);

  const handleReload = () => {
    setIsLoading(true);
    setError(null);
    
    // Simulate reload
    setTimeout(() => {
      setIsLoading(false);
    }, 1000);
  };

  if (isLoading) {
    return (
      <div className="w-full h-full bg-gray-900 rounded-lg border border-gray-700 flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-green-400 mx-auto mb-4"></div>
          <p className="text-gray-400">Loading chart...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="w-full h-full relative">
      <FallbackChart />
      
      {error && (
        <div className="absolute inset-0 bg-gray-900 bg-opacity-90 flex items-center justify-center">
          <div className="text-center">
            <div className="text-yellow-400 text-4xl mb-4">⚠️</div>
            <h3 className="text-xl font-semibold text-white mb-2">Chart Error</h3>
            <p className="text-gray-400 mb-4">{error}</p>
            <button
              onClick={handleReload}
              className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded transition-colors"
            >
              Reload
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default Chart;
